import assert from 'node:assert/strict'
import {readFile} from 'node:fs/promises'
import {createProcedureStorePre} from '../../lib/procedure-store.js'
import {sessionRefOf} from '../../lib/evidence-store.js'
let pass=0,fail=0
for(const mode of ['raw','truncated']){
 // Immutable snapshots generated by the complete production store at 54eede1,
 // before identity-version migration was added; no reconstructed fake shape.
 const data=JSON.parse(await readFile(new URL('../fixtures/audit-followup/procedure-session-'+mode+'.json',import.meta.url),'utf8'))
 const fullA=mode==='raw'?'A':'A'.repeat(64),s=createProcedureStorePre();assert.equal(s.restore(data).ok,true);const pid=s.query()[0].procedureId
 try{
  assert.equal(s.query()[0].evidence.sessions,mode==='raw'?2:1,'unrecoverable >=24-char legacy prefixes do not count as proven full identities')
  s.addEvidence(pid,{kind:'read',sessionRef:sessionRefOf(fullA)});s.addEvidence(pid,{kind:'success',sessionRef:sessionRefOf(fullA)})
  assert.equal(s.query()[0].evidence.sessions,2,'same old A cannot become a third session after hashing')
  assert.equal(s.promote(pid).promoted,false,'migration cannot create diversity sufficient for promotion')
  const restored=createProcedureStorePre();assert.equal(restored.restore(JSON.parse(JSON.stringify(s.snapshot()))).ok,true)
  restored.addEvidence(pid,{kind:'read',sessionRef:sessionRefOf(fullA)});assert.equal(restored.query()[0].evidence.sessions,2,'new snapshot reload keeps dedup identity')
  restored.addEvidence(pid,{kind:'read',sessionRef:sessionRefOf('C')});assert.equal(restored.query()[0].evidence.sessions,3,'genuinely new C counts exactly once')
  restored.addEvidence(pid,{kind:'read',sessionRef:'C'});assert.equal(restored.query()[0].evidence.sessions,3,'legacy short caller C and hashed C converge')
  if(mode==='truncated')assert.deepEqual(restored.snapshot().procedures[0]._legacySessions,['A'.repeat(48)],'ambiguous prefix retained for inspection, not counted')
  console.log('PASS '+mode+' snapshot upgrade');pass++
 }catch(e){console.error('FAIL '+mode+' '+e.stack);fail++}
}
console.log('PASS '+pass+' / FAIL '+fail);process.exitCode=fail?1:0
